CREATE FUNCTION test_candidate(f text,s text) RETURNS jsonb LANGUAGE sql AS $$ SELECT jsonb_build_object('familia',f,'etapa',s,'lead_id','10000000-0000-0000-0000-000000000001','unidade_id','00000000-0000-0000-0000-000000000001','ciclo_id','20000000-0000-0000-0000-000000000001') $$;
CREATE FUNCTION test_assert(v boolean,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF v IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAIL: %',label; END IF; RAISE NOTICE 'PASS: %',label; END $$;
SELECT test_assert(fu_transicao_matriz('R01','D+1')=ARRAY['MATRICULADOS'],'R01 D+1');
SELECT test_assert(fu_transicao_matriz('R01','D+7')=ARRAY['TECNICO_M7'],'R01 D+7');
SELECT test_assert(fu_transicao_matriz('R01','D+30')=ARRAY['TECNICO_M21','GERENCIAL_M30'],'R01 D+30 requires both');
SELECT test_assert(fu_transicao_matriz('R02','M+7')=ARRAY['TECNICO_M7'],'R02 M+7');
SELECT test_assert(fu_transicao_matriz('R02','M+30')=ARRAY['GERENCIAL_M30'],'R02 M+30');
SELECT test_assert(fu_transicao_matriz('G02','G+7')=ARRAY['TECNICO_M7'],'G02 G+7');
SELECT test_assert(fu_transicao_matriz('G02','G+30')=ARRAY['GERENCIAL_M30'],'G02 G+30');
SELECT test_assert((fu_transicao_avaliar(test_candidate('R01','D+1'))->>'suprimir')::boolean=false,'default observation no suppression');
INSERT INTO fu_transicao_config(unidade_id,familia,modo) VALUES('00000000-0000-0000-0000-000000000001','R01','LEGADO');
SELECT test_assert(fu_transicao_avaliar(test_candidate('R01','D+1'))->>'modo'='LEGADO','legacy unchanged');
UPDATE fu_transicao_config SET modo='OBSERVACAO';
SELECT test_assert(fu_transicao_avaliar(test_candidate('R01','D+7'))->>'motivo'='sobreposicao_identificada_sem_supressao','observation identifies overlap');
SELECT fu_transicao_avaliar(test_candidate('R01','D+7'));
SELECT test_assert((SELECT count(*) FROM fu_transicao_eventos WHERE familia='R01' AND etapa='D+7')=1,'reexecution idempotent');
DO $$ BEGIN BEGIN UPDATE fu_transicao_config SET modo='NOVO',ciclos_desde='2026-11-02',aprovado_em=now(),aprovacao='isolated'; RAISE EXCEPTION 'FAIL accepted unhomologated mode'; EXCEPTION WHEN raise_exception THEN IF SQLERRM LIKE 'FAIL%' THEN RAISE; END IF; END; END $$;
INSERT INTO fu_transicao_homologacoes SELECT '00000000-0000-0000-0000-000000000001',s,'{"geracao":true,"grupo_correto":true,"mensagem_campos":true,"abrir":true,"enviado":true,"edicao_original":true,"acompanhamento_separado":true,"resultado":true,"sem_retroativos":true,"evento_legitimo":true,"historico_consultado":true}',now(),'ISOLATED FAKE EVIDENCE',now() FROM unnest(ARRAY['MATRICULADOS','TECNICO_M7','TECNICO_M21','GERENCIAL_M30']) s;
UPDATE fu_transicao_config SET modo='NOVO',ciclos_desde='2026-11-02',aprovado_em=now(),aprovacao='ISOLATED ONLY';
SELECT test_assert((fu_transicao_avaliar(test_candidate('R01','D+30'))->>'suprimir')::boolean,'new suppresses exact eligible cycle');
SELECT test_assert((fu_transicao_avaliar(test_candidate('G02','G+30'))->>'suprimir')::boolean=false,'disabled family unchanged');
UPDATE tasks SET fu_tecnico_status='cancelado' WHERE fu_tecnico_etapa='M+21';
SELECT test_assert((fu_transicao_avaliar(test_candidate('R01','D+30'))->>'suprimir')::boolean=false,'missing operational replacement preserves legacy');
UPDATE tasks SET fu_tecnico_status='pendente' WHERE fu_tecnico_etapa='M+21';
UPDATE interacoes SET tipo='RENOVACAO';
SELECT test_assert((fu_transicao_avaliar(test_candidate('R01','D+1'))->>'suprimir')::boolean=false,'renewal excluded');
UPDATE interacoes SET tipo='MATRICULA',created_at='2026-10-01';
SELECT test_assert((fu_transicao_avaliar(test_candidate('R01','D+7'))->>'suprimir')::boolean=false,'old cycles protected');
UPDATE interacoes SET created_at='2026-11-02T12:00:00Z';
SELECT test_assert((fu_transicao_avaliar(test_candidate('R02','M+7')-'ciclo_id'||jsonb_build_object('referencia','2026-11-02','legado_id','30000000-0000-0000-0000-000000000002'))->>'suprimir')::boolean=false,'R02 not enabled');
DO $$ BEGIN BEGIN PERFORM fu_transicao_avaliar(test_candidate('R01','D+7')||'{"legado_id":"30000000-0000-0000-0000-000000000001"}'); RAISE EXCEPTION 'FAIL commercial accepted'; EXCEPTION WHEN raise_exception THEN IF SQLERRM LIKE 'FAIL%' THEN RAISE; END IF; END; END $$;
SELECT test_assert((SELECT status FROM follow_ups WHERE tipo='D+7')='concluido','commercial history preserved');
SELECT test_assert((SELECT status FROM follow_ups WHERE tipo='M+7')='pendente','legacy not fictitiously completed');
